{"implementation": "def solve(case):
    if not isinstance(case, dict) or 'segments' not in case or 'budget' not in case:
        raise ValueError('Missing required fields')
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('No segments')
    segs = []
    for i, seg in enumerate(segments):
        if not isinstance(seg, dict) or 'name' not in seg or 'importance' not in seg or 'minimum' not in seg or 'capacity' not in seg:
            raise ValueError(f'Invalid segment at index {i}')
        name = seg['name']
        imp = seg['importance']
        min_ = seg['minimum']
        cap = seg['capacity']
        if not isinstance(imp, (int, float)) or not isinstance(min_, (int, float)) or not isinstance(cap, (int, float)):
            raise ValueError(f'Invalid segment types at index {i}')
        segs.append({'name': name, 'importance': imp, 'minimum': int(min_), 'capacity': int(cap), 'index': i})
    if not isinstance(budget, (int, float)):
        raise ValueError('Budget must be int or float')
    budget = int(budget)
    total_min = sum(s['minimum'] for s in segs)
    total_cap = sum(s['capacity'] for s in segs)
    if budget < total_min:
        raise ValueError('Budget below sum of minimum quotas')
    if budget > total_cap:
        raise ValueError('Budget exceeds total capacity')
    alloc = [s['minimum'] for s in segs]
    remaining = budget - total_min
    while remaining > 0:
        best_index = None
        best_ratio = -1
        for i, s in enumerate(segs):
            cap = s['capacity']
            cur = alloc[i]
            if cur >= cap:
                continue
            ratio = s['importance'] / (cur + 1)
            if ratio > best_ratio or (ratio == best_ratio and (best_index is None or i < best_index)):
                best_ratio = ratio
                best_index = i
        if best_index is None:
            raise ValueError('Insufficient capacity to allocate remaining budget (unexpected)')
        alloc[best_index] += 1
        remaining -= 1
    by_name = {}
    for i, s in enumerate(segs):
        by_name[s['name']] = alloc[i]
    total = sum(alloc)
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"}
